import {GRASS,BUILDINGS,buildingSettings} from './scenery.js';
const $=s=>document.querySelector(s);
export function mountScenery(api){const panel=document.createElement('section');panel.className='panel-section scenery-panel';panel.innerHTML=`<div class="section-heading"><span class="section-num">LAND</span><h2>Ground & buildings</h2></div><p class="field-hint">Grass fills the infield and all empty ground automatically, including the exported mod.</p><div class="grass-swatches">${Object.entries(GRASS).map(([k,v])=>`<button data-grass="${k}" aria-pressed="false"><i style="background:rgb(${v.color})"></i>${v.label}</button>`).join('')}</div><label class="toggle-row"><span>Grass blades in game · CSP</span><input id="grass-fx" type="checkbox" checked><span class="toggle"></span></label><p class="field-hint">Requires Custom Shaders Patch with Grass FX enabled. The grass base stays colored without CSP.</p><div class="building-heading"><b id="building-heading">Building brush</b><span id="building-count" class="scene-tag"></span></div><label class="studio-field">Building type<select id="building-type">${Object.entries(BUILDINGS).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><div class="studio-fields"><label class="studio-field">Width · m<input id="building-width" type="number" min="3" max="60" step="1"></label><label class="studio-field">Depth · m<input id="building-depth" type="number" min="3" max="40" step="1"></label><label class="studio-field">Height · m<input id="building-height" type="number" min="3" max="30" step="1"></label><label class="studio-field">Rotation · °<input id="building-rotation" type="number" min="0" max="359" step="1"></label></div><div class="building-rotation-controls"><input id="building-angle-slider" type="range" min="0" max="359" step="1" aria-label="Building rotation"><div><button data-rotate="-15">↶ −15°</button><button data-rotate="15">+15° ↷</button><button data-rotate="90">Turn 90°</button></div></div><label class="studio-field">Roof finish<select id="building-roof"><option value="graphite">Graphite</option><option value="terracotta">Terracotta</option><option value="blue">Blue steel</option></select></label><div class="analysis-actions"><button id="place-building" class="outline-button">Place building · U</button><button id="remove-building" class="tree-remove" hidden>Remove building</button></div><p class="field-hint">Click clear ground to place. Use Move to select or drag a building. Rotate with the handle above a selected building, the angle slider, or R / Shift+R. Hold Shift while dragging to snap to 15°.</p><div id="building-list" class="building-list"></div>`;$('.environment-panel').after(panel);
 panel.querySelectorAll('[data-grass]').forEach(b=>b.onclick=()=>api.updateTrack(t=>t.grass=b.dataset.grass));
 $('#grass-fx').onchange=()=>api.updateTrack(t=>t.export={...t.export,grassFx:$('#grass-fx').checked});
 $('#place-building').onclick=()=>{api.selectBuilding(-1);api.setTool('building');};$('#remove-building').onclick=()=>{const i=api.getBuilding();if(i>=0)api.updateTrack(t=>t.buildings.splice(i,1));};
 for(const key of ['type','width','depth','height','rotation','roof'])$('#building-'+key).onchange=()=>{const i=api.getBuilding(),values={...api.getBuildingBrush()};for(const k of ['type','width','depth','height','rotation','roof']){const input=$('#building-'+k);values[k]=input.type==='number'?Number(input.value):input.value;if(input.type==='number'&&!input.checkValidity()){api.toast('Use a value within the building dimensions shown.');refresh();return;}}if(key==='type')Object.assign(values,BUILDINGS[values.type]);const sanitized=buildingSettings(values);api.setBuildingBrush(sanitized);if(i>=0)api.updateTrack(t=>Object.assign(t.buildings[i],sanitized));refresh();};
 $('#building-angle-slider').oninput=()=>$('#building-rotation').value=$('#building-angle-slider').value;$('#building-angle-slider').onchange=()=>$('#building-rotation').onchange();panel.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=()=>api.rotateBuilding(Number(b.dataset.rotate)));
 function refresh(){const t=api.getTrack(),i=api.getBuilding(),b=t.buildings?.[i],brush=b||api.getBuildingBrush();panel.querySelectorAll('[data-grass]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.grass===(t.grass||'mown'))));$('#grass-fx').checked=t.export?.grassFx!==false;$('#building-count').textContent=`${t.buildings?.length||0} / 60`;$('#building-heading').textContent=b?`${BUILDINGS[b.type].label} ${i+1}`:'Building brush';for(const key of ['type','width','depth','height','rotation','roof'])$('#building-'+key).value=brush[key];$('#building-angle-slider').value=brush.rotation;$('#remove-building').hidden=!b;const list=$('#building-list');list.replaceChildren();(t.buildings||[]).forEach((v,index)=>{const button=document.createElement('button');button.textContent=`${BUILDINGS[v.type].label} ${index+1} · ${v.width} × ${v.depth} m`;button.classList.toggle('selected',index===i);button.onclick=()=>api.selectBuilding(index);list.append(button);});}
 return {refresh};}
